const pptxgen = require("pptxgenjs");
const React = require("react");
const ReactDOMServer = require("react-dom/server");
const sharp = require("sharp");
const { FaUsers, FaBrain, FaMedkit, FaHeartbeat, FaFemale, FaMale, FaHandHoldingHeart, FaPills, FaChurch, FaComments, FaExclamationTriangle, FaGlobe, FaChartBar } = require("react-icons/fa");

// Color palette - Sage Calm / mental health theme
const COLORS = {
  darkBg: "2C3E50",       // Deep slate - title slides
  primary: "3498DB",       // Calming blue
  secondary: "9B59B6",     // Purple (mental health awareness)
  accent: "E74C3C",        // Red accent for callouts
  accentAlt: "27AE60",     // Green for positive indicators
  lightBg: "F5F7FA",        // Light gray-blue for content
  white: "FFFFFF",
  text: "2C3E50",
  textLight: "7F8C8D",
  bar1: "3498DB",          // Depressive disorders
  bar2: "9B59B6",          // Anxiety disorders
  bar3: "E67E22",          // Schizophrenia
  bar4: "E74C3C",          // Bipolar
  bar5: "27AE60",          // Eating disorders
};

// Helper to render icons to base64 PNG
function renderIconSvg(IconComponent, color = "#000000", size = 256) {
  return ReactDOMServer.renderToStaticMarkup(
    React.createElement(IconComponent, { color, size: String(size) })
  );
}

async function iconToBase64Png(IconComponent, color, size = 256) {
  const svg = renderIconSvg(IconComponent, color, size);
  const pngBuffer = await sharp(Buffer.from(svg)).png().toBuffer();
  return "image/png;base64," + pngBuffer.toString("base64");
}

async function main() {
  const pres = new pptxgen();
  pres.layout = "LAYOUT_16x9";
  pres.author = "Our World in Data / IHME";
  pres.title = "The Global Burden of Mental Illness: Prevalence, Impact, and the Treatment Gap";

  // Pre-generate icons
  const iconFemale = await iconToBase64Png(FaFemale, "#FFFFFF", 256);
  const iconMale = await iconToBase64Png(FaMale, "#FFFFFF", 256);
  const iconBrain = await iconToBase64Png(FaBrain, "#3498DB", 256);
  const iconMedkit = await iconToBase64Png(FaMedkit, "#E74C3C", 256);
  const iconExclamation = await iconToBase64Png(FaExclamationTriangle, "#E67E22", 256);
  const iconUsers = await iconToBase64Png(FaUsers, "#9B59B6", 256);
  const iconHeart = await iconToBase64Png(FaHeartbeat, "#E74C3C", 256);
  const iconGlobe = await iconToBase64Png(FaGlobe, "#3498DB", 256);
  const iconPills = await iconToBase64Png(FaPills, "#27AE60", 256);
  const iconChurch = await iconToBase64Png(FaChurch, "#9B59B6", 256);
  const iconComments = await iconToBase64Png(FaComments, "#3498DB", 256);
  const iconChartBar = await iconToBase64Png(FaChartBar, "#FFFFFF", 256);
  const iconHandHeart = await iconToBase64Png(FaHandHoldingHeart, "#E74C3C", 256);

  // ========== SLIDE 1: Title Slide ==========
  let slide1 = pres.addSlide();
  slide1.background = { color: COLORS.darkBg };

  // Accent line at top
  slide1.addShape(pres.shapes.RECTANGLE, {
    x: 0, y: 0, w: 10, h: 0.08,
    fill: { color: COLORS.primary }
  });

  // Main title
  slide1.addText("The Global Burden of Mental Illness", {
    x: 0.5, y: 1.5, w: 9, h: 0.9,
    fontSize: 40, fontFace: "Arial", bold: true,
    color: COLORS.white, align: "center", margin: 0
  });

  // Subtitle
  slide1.addText("Prevalence, Impact, and the Treatment Gap", {
    x: 0.5, y: 2.4, w: 9, h: 0.5,
    fontSize: 24, fontFace: "Arial",
    color: COLORS.primary, align: "center", margin: 0
  });

  // Divider line
  slide1.addShape(pres.shapes.RECTANGLE, {
    x: 3.5, y: 3.1, w: 3, h: 0.03,
    fill: { color: COLORS.primary }
  });

  // Source attribution
  slide1.addText("Source: Our World in Data / IHME Global Burden of Disease, 2023", {
    x: 0.5, y: 3.5, w: 9, h: 0.4,
    fontSize: 14, fontFace: "Arial",
    color: COLORS.textLight, align: "center", margin: 0
  });

  // Footer note
  slide1.addText("For public health policy analysts and mental health program planners", {
    x: 0.5, y: 5.0, w: 9, h: 0.3,
    fontSize: 12, fontFace: "Arial", italic: true,
