  slide2.addText("1 in 3", {
    x: 0.8, y: 2.7, w: 3.6, h: 0.9,
    fontSize: 52, fontFace: "Arial", bold: true,
    color: COLORS.accent, align: "center", margin: 0
  });
  slide2.addText("women", {
    x: 0.8, y: 3.5, w: 3.6, h: 0.4,
    fontSize: 22, fontFace: "Arial",
    color: COLORS.text, align: "center", margin: 0
