const pptxgen = require("pptxgenjs");
const React = require("react");
const ReactDOMServer = require("react-dom/server");
const sharp = require("sharp");
const { FaUsers, FaBrain, FaMedkit, FaHeartbeat, FaFemale, FaMale, FaHandHoldingHeart, FaPills, FaChurch, FaComments, FaExclamationTriangle, FaGlobe } = require("react-icons/fa");

// Color palette - Sage Calm / mental health theme
const COLORS = {
  darkBg: "2C3E50",
  primary: "3498DB",
  secondary: "9B59B6",
  accent: "E74C3C",
  accentAlt: "27AE60",
  lightBg: "F5F7FA",
  white: "FFFFFF",
  text: "2C3E50",
  textLight: "7F8C8D",
  cardBg: "3D5266",
};

// Helper to render icons to base64 PNG
function renderIconSvg(IconComponent, color = "#000000", size = 256) {
  return ReactDOMServer.renderToStaticMarkup(
    React.createElement(IconComponent, { color, size: String(size) })
  );
}

async function iconToBase64Png(IconComponent, color, size = 256) {
  const svg = renderIconSvg(IconComponent, color, size);
  const pngBuffer = await sharp(Buffer.from(svg)).png().toBuffer();
  return "image/png;base64," + pngBuffer.toString("base64");
}

async function main() {
  const pres = new pptxgen();
  pres.layout = "LAYOUT_16x9";
  pres.author = "Our World in Data / IHME";
  pres.title = "The Global Burden of Mental Illness: Prevalence, Impact, and the Treatment Gap";

  // Pre-generate icons - using WHITE icons on colored circles for visibility
  const iconFemale = await iconToBase64Png(FaFemale, "#FFFFFF", 256);
  const iconMale = await iconToBase64Png(FaMale, "#FFFFFF", 256);
  const iconBrain = await iconToBase64Png(FaBrain, "#FFFFFF", 256);
  const iconHeart = await iconToBase64Png(FaHeartbeat, "#FFFFFF", 256);
  const iconExclamation = await iconToBase64Png(FaExclamationTriangle, "#FFFFFF", 256);
  const iconUsers = await iconToBase64Png(FaUsers, "#FFFFFF", 256);
  const iconGlobe = await iconToBase64Png(FaGlobe, "#FFFFFF", 256);
  const iconMedkit = await iconToBase64Png(FaMedkit, "#FFFFFF", 256);
  const iconPills = await iconToBase64Png(FaPills, "#FFFFFF", 256);
  const iconChurch = await iconToBase64Png(FaChurch, "#FFFFFF", 256);
  const iconComments = await iconToBase64Png(FaComments, "#FFFFFF", 256);

  // ========== SLIDE 1: Title Slide ==========
  let slide1 = pres.addSlide();
  slide1.background = { color: COLORS.darkBg };

  slide1.addShape(pres.shapes.RECTANGLE, {
    x: 0, y: 0, w: 10, h: 0.08,
    fill: { color: COLORS.primary }
  });

  slide1.addText("The Global Burden of Mental Illness", {
    x: 0.5, y: 1.5, w: 9, h: 0.9,
    fontSize: 40, fontFace: "Arial", bold: true,
    color: COLORS.white, align: "center", margin: 0
  });

  slide1.addText("Prevalence, Impact, and the Treatment Gap", {
    x: 0.5, y: 2.4, w: 9, h: 0.5,
    fontSize: 24, fontFace: "Arial",
    color: COLORS.primary, align: "center", margin: 0
  });

  slide1.addShape(pres.shapes.RECTANGLE, {
    x: 3.5, y: 3.1, w: 3, h: 0.03,
    fill: { color: COLORS.primary }
  });

  slide1.addText("Source: Our World in Data / IHME Global Burden of Disease, 2023", {
    x: 0.5, y: 3.5, w: 9, h: 0.4,
    fontSize: 14, fontFace: "Arial",
    color: COLORS.textLight, align: "center", margin: 0
  });

  slide1.addText("For public health policy analysts and mental health program planners", {
    x: 0.5, y: 5.0, w: 9, h: 0.3,
    fontSize: 12, fontFace: "Arial", italic: true,
    color: COLORS.textLight, align: "center", margin: 0
  });

  // ========== SLIDE 2: Prevalence - Large Callout Numbers ==========
  let slide2 = pres.addSlide();
  slide2.background = { color: COLORS.lightBg };

  slide2.addText("Hundreds of Millions Affected", {
    x: 0.5, y: 0.4, w: 9, h: 0.7,
    fontSize: 32, fontFace: "Arial", bold: true,
    color: COLORS.text, align: "left", margin: 0
  });

  slide2.addText("Major Depression Lifetime Risk", {
    x: 0.5, y: 1.05, w: 9, h: 0.35,
    fontSize: 16, fontFace: "Arial",
    color: COLORS.textLight, align: "left", margin: 0
  });

  // Left card - Women
  slide2.addShape(pres.shapes.RECTANGLE, {
    x: 0.5, y: 1.55, w: 4.2, h: 3.0,
    fill: { color: COLORS.white },
    shadow: { type: "outer", color: "000000", blur: 8, offset: 3, angle: 135, opacity: 0.1 }
  });
  slide2.addShape(pres.shapes.RECTANGLE, {
    x: 0.5, y: 1.55, w: 0.08, h: 3.0,
    fill: { color: COLORS.accent }
  });

  // Female icon circle background
  slide2.addShape(pres.shapes.OVAL, {
    x: 1.9, y: 1.75, w: 0.9, h: 0.9,
    fill: { color: COLORS.accent }
  });
  slide2.addImage({ data: iconFemale, x: 2.1, y: 1.95, w: 0.5, h: 0.5 });

  slide2.addText("1 in 3", {
    x: 0.7, y: 2.75, w: 3.8, h: 0.8,
    fontSize: 48, fontFace: "Arial", bold: true,
    color: COLORS.accent, align: "center", margin: 0
  });
  slide2.addText("women", {
    x: 0.7, y: 3.5, w: 3.8, h: 0.4,
    fontSize: 20, fontFace: "Arial",
    color: COLORS.text, align: "center", margin: 0
  });
  slide2.addText("will experience major depression\nin their lifetime", {
    x: 0.7, y: 3.95, w: 3.8, h: 0.55,
    fontSize: 12, fontFace: "Arial",
    color: COLORS.textLight, align: "center", margin: 0
  });

  // Right card - Men
  slide2.addShape(pres.shapes.RECTANGLE, {
    x: 5.3, y: 1.55, w: 4.2, h: 3.0,
    fill: { color: COLORS.white },
    shadow: { type: "outer", color: "000000", blur: 8, offset: 3, angle: 135, opacity: 0.1 }
  });
  slide2.addShape(pres.shapes.RECTANGLE, {
    x: 5.3, y: 1.55, w: 0.08, h: 3.0,
    fill: { color: COLORS.primary }
  });

  // Male icon circle background
  slide2.addShape(pres.shapes.OVAL, {
    x: 6.7, y: 1.75, w: 0.9, h: 0.9,
    fill: { color: COLORS.primary }
  });
  slide2.addImage({ data: iconMale, x: 6.9, y: 1.95, w: 0.5, h: 0.5 });

  slide2.addText("1 in 5", {
    x: 5.5, y: 2.75, w: 3.8, h: 0.8,
    fontSize: 48, fontFace: "Arial", bold: true,
    color: COLORS.primary, align: "center", margin: 0
  });
  slide2.addText("men", {
    x: 5.5, y: 3.5, w: 3.8, h: 0.4,
    fontSize: 20, fontFace: "Arial",
    color: COLORS.text, align: "center", margin: 0
  });
  slide2.addText("will experience major depression\nin their lifetime", {
    x: 5.5, y: 3.95, w: 3.8, h: 0.55,
    fontSize: 12, fontFace: "Arial",
    color: COLORS.textLight, align: "center", margin: 0
  });

  // Bottom note
  slide2.addText("Other conditions such as schizophrenia and bipolar disorder are less common but carry severe individual impact.", {
    x: 0.5, y: 4.8, w: 9, h: 0.4,
    fontSize: 11, fontFace: "Arial", italic: true,
    color: COLORS.textLight, align: "center", margin: 0
  });

  // ========== SLIDE 3: Burden by Category - Horizontal Bar Chart ==========
  let slide3 = pres.addSlide();
  slide3.background = { color: COLORS.white };

  slide3.addText("Depression and Anxiety Dominate Disease Burden", {
    x: 0.5, y: 0.35, w: 9, h: 0.6,
    fontSize: 28, fontFace: "Arial", bold: true,
    color: COLORS.text, align: "left", margin: 0
  });

  slide3.addText("DALYs per 100,000 people, World 2023", {
    x: 0.5, y: 0.9, w: 9, h: 0.35,
    fontSize: 14, fontFace: "Arial",
    color: COLORS.textLight, align: "left", margin: 0
  });

  const chartData = [{
    name: "DALYs per 100,000",
    labels: ["Depressive\nDisorders", "Anxiety\nDisorders", "Schizophrenia", "Bipolar\nDisorder", "Eating\nDisorders"],
    values: [694.6, 686.5, 210.2, 94.6, 47.5]
  }];

  slide3.addChart(pres.charts.BAR, chartData, {
    x: 0.5, y: 1.35, w: 9, h: 3.7,
    barDir: "bar",
    chartColors: [COLORS.primary],
    chartArea: { fill: { color: COLORS.white } },
    catAxisLabelColor: COLORS.text,
    catAxisLabelFontSize: 11,
    catAxisLabelFontBold: true,
    valAxisLabelColor: COLORS.textLight,
    valAxisLabelFontSize: 10,
    valGridLine: { color: "E8E8E8", size: 0.5 },
    catGridLine: { style: "none" },
    showValue: true,
    dataLabelPosition: "outEnd",
    dataLabelColor: COLORS.text,
    dataLabelFontSize: 11,
    showLegend: false,
    valAxisMaxVal: 750,
    barGapWidthPct: 50,
  });

  slide3.addText("Source: IHME, Global Burden of Disease, 2023", {
    x: 0.5, y: 5.2, w: 9, h: 0.3,
    fontSize: 10, fontFace: "Arial", italic: true,
    color: COLORS.textLight, align: "left", margin: 0
  });

  // ========== SLIDE 4: Depression vs Anxiety Parity ==========
  let slide4 = pres.addSlide();
  slide4.background = { color: COLORS.lightBg };

  slide4.addText("Near-Equal Burden: Depression vs. Anxiety", {
    x: 0.5, y: 0.4, w: 9, h: 0.6,
    fontSize: 28, fontFace: "Arial", bold: true,
    color: COLORS.text, align: "left", margin: 0
  });

  slide4.addText("Together they account for ~80% of mental health disease burden", {
    x: 0.5, y: 0.95, w: 9, h: 0.35,
    fontSize: 14, fontFace: "Arial",
    color: COLORS.textLight, align: "left", margin: 0
  });

  // Depressive disorders card
  slide4.addShape(pres.shapes.RECTANGLE, {
    x: 0.5, y: 1.45, w: 4.2, h: 2.5,
    fill: { color: COLORS.white },
    shadow: { type: "outer", color: "000000", blur: 6, offset: 2, angle: 135, opacity: 0.1 }
  });

  // Blue circle for brain icon
  slide4.addShape(pres.shapes.OVAL, {
    x: 1.95, y: 1.6, w: 0.9, h: 0.9,
    fill: { color: COLORS.primary }
  });
  slide4.addImage({ data: iconBrain, x: 2.15, y: 1.8, w: 0.5, h: 0.5 });

  slide4.addText("694.6", {
    x: 0.7, y: 2.55, w: 3.8, h: 0.65,
    fontSize: 42, fontFace: "Arial", bold: true,
    color: COLORS.primary, align: "center", margin: 0
  });
  slide4.addText("DALYs per 100K", {
    x: 0.7, y: 3.15, w: 3.8, h: 0.3,
    fontSize: 13, fontFace: "Arial",
    color: COLORS.textLight, align: "center", margin: 0
  });
  slide4.addText("Depressive Disorders", {
    x: 0.7, y: 3.5, w: 3.8, h: 0.35,
    fontSize: 16, fontFace: "Arial", bold: true,
    color: COLORS.text, align: "center", margin: 0
  });

  // Anxiety disorders card
  slide4.addShape(pres.shapes.RECTANGLE, {
    x: 5.3, y: 1.45, w: 4.2, h: 2.5,
    fill: { color: COLORS.white },
    shadow: { type: "outer", color: "000000", blur: 6, offset: 2, angle: 135, opacity: 0.1 }
  });

  // Purple circle for heart icon
  slide4.addShape(pres.shapes.OVAL, {
    x: 6.75, y: 1.6, w: 0.9, h: 0.9,
    fill: { color: COLORS.secondary }
  });
  slide4.addImage({ data: iconHeart, x: 6.95, y: 1.8, w: 0.5, h: 0.5 });

  slide4.addText("686.5", {
    x: 5.5, y: 2.55, w: 3.8, h: 0.65,
    fontSize: 42, fontFace: "Arial", bold: true,
    color: COLORS.secondary, align: "center", margin: 0
  });
  slide4.addText("DALYs per 100K", {
    x: 5.5, y: 3.15, w: 3.8, h: 0.3,
    fontSize: 13, fontFace: "Arial",
    color: COLORS.textLight, align: "center", margin: 0
  });
  slide4.addText("Anxiety Disorders", {
    x: 5.5, y: 3.5, w: 3.8, h: 0.35,
    fontSize: 16, fontFace: "Arial", bold: true,
    color: COLORS.text, align: "center", margin: 0
  });

  // Difference callout
  slide4.addShape(pres.shapes.RECTANGLE, {
    x: 1.5, y: 4.15, w: 7, h: 0.65,
    fill: { color: COLORS.darkBg }
  });
  slide4.addText("Only 1.2% difference in disease burden — nearly identical impact", {
    x: 1.5, y: 4.15, w: 7, h: 0.65,
    fontSize: 14, fontFace: "Arial", bold: true,
    color: COLORS.white, align: "center", valign: "middle", margin: 0
  });

  // Bottom note
  slide4.addText("Combined, depression and anxiety represent the overwhelming majority of mental health DALYs worldwide.", {
    x: 0.5, y: 4.95, w: 9, h: 0.35,
    fontSize: 11, fontFace: "Arial", italic: true,
    color: COLORS.textLight, align: "center", margin: 0
  });

  // ========== SLIDE 5: Severe Conditions - Schizophrenia & Bipolar ==========
  let slide5 = pres.addSlide();
  slide5.background = { color: COLORS.white };

  slide5.addText("Severe Conditions: High Individual Impact", {
    x: 0.5, y: 0.4, w: 9, h: 0.6,
    fontSize: 28, fontFace: "Arial", bold: true,
    color: COLORS.text, align: "left", margin: 0
  });

  slide5.addText("Lower population prevalence but disproportionate individual disability", {
    x: 0.5, y: 0.95, w: 9, h: 0.35,
    fontSize: 14, fontFace: "Arial",
    color: COLORS.textLight, align: "left", margin: 0
  });

  // Schizophrenia card
  slide5.addShape(pres.shapes.RECTANGLE, {
    x: 0.5, y: 1.45, w: 4.2, h: 2.7,
    fill: { color: "FDF2F2" },
    shadow: { type: "outer", color: "000000", blur: 6, offset: 2, angle: 135, opacity: 0.08 }
  });
  slide5.addShape(pres.shapes.RECTANGLE, {
    x: 0.5, y: 1.45, w: 0.08, h: 2.7,
    fill: { color: "E67E22" }
  });

  // Orange circle for exclamation icon
  slide5.addShape(pres.shapes.OVAL, {
    x: 1.95, y: 1.6, w: 0.9, h: 0.9,
    fill: { color: "E67E22" }
  });
  slide5.addImage({ data: iconExclamation, x: 2.15, y: 1.8, w: 0.5, h: 0.5 });

  slide5.addText("210.2", {
    x: 0.7, y: 2.55, w: 3.8, h: 0.65,
    fontSize: 42, fontFace: "Arial", bold: true,
    color: "E67E22", align: "center", margin: 0
  });
  slide5.addText("DALYs per 100K", {
    x: 0.7, y: 3.15, w: 3.8, h: 0.3,
    fontSize: 13, fontFace: "Arial",
    color: COLORS.textLight, align: "center", margin: 0
  });
  slide5.addText("Schizophrenia", {
    x: 0.7, y: 3.5, w: 3.8, h: 0.35,
    fontSize: 18, fontFace: "Arial", bold: true,
    color: COLORS.text, align: "center", margin: 0
  });
  slide5.addText("Disproportionate burden relative to prevalence", {
